var ids = []
for r in StratagemManager.get_heroic_intervention_eligible_units_11e(1):
	ids.append(str(r.get("unit_id", "")))
return "|".join(ids)

var bad = []
for c in tree.root.get_node("HeroicInterventionDialog/Content/UnitScroll/UnitList").get_children():
	var uid = str(c.name).substr(4)
	if RulesEngine.is_attached_character(uid, GameState.state):
		bad.append(uid + ":attached")
	if RulesEngine.is_attached_unit_engaged(uid, GameState.state):
		bad.append(uid + ":engaged")
return "|".join(bad)
